constraints:
1 ≤ N ≤ 10^{5}
1 ≤ S, A_{i} , X ≤ 10^{18}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def isPossible(self, S, N, X, A):
		newArray = [S]
		sumArr = newArray[0]
		temp = 0
		for i in range(1, N + 1):
			newArray.append(A[i - 1] + sumArr)
			if newArray[i] > X:
				temp = i
				break
			sumArr += newArray[i]
		for i in range(temp - 1, -1, -1):
			if X < newArray[i]:
				continue
			else:
				X -= newArray[i]
			if X == 0:
				return 1
		return 0
